    /* 投喂不出声时最麻烦的是什么错误都看不见。这里把关键状态写进 DIAG_KEY，
       即使不开 Console 也能事后查明「服务没拿到 / 会话 id 没拿到 / prompt 被拒」。 */

    function diag(kind, extra) {
      var row = { at: Date.now(), kind: String(kind) }
      if (extra && typeof extra === 'object') {
        Object.keys(extra).forEach(function (k) {
          var v = extra[k]
          if (v === null || v === undefined) row[k] = ''
          else if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') row[k] = v
          else row[k] = String(v)
        })
      }
      var rows = (store.state.diag || []).concat([row]).slice(-14)
      store.set({ diag: rows })
      try {
        localStorage.setItem(DIAG_KEY, JSON.stringify({ at: Date.now(), rows: rows }))
      } catch (e) { /* 存不下就算了，不影响主流程 */ }
      return row
    }

    function lookupSessions() {
      var ctx = clientCtx
      if (!ctx) return null
      /* 先走 ctx.get：这是「可选依赖」的官方口子，不声明 inject 也能取。
         直接读 ctx.sessions 在没声明依赖时会抛错，必须兜住，否则点击投喂会静默炸掉。 */
      try {
        if (typeof ctx.get === 'function') {
          var svc = ctx.get('sessions')
          if (svc) return svc
        }
      } catch (e) { /* 取不到就试下面的 */ }
      try {
        if (ctx.sessions) return ctx.sessions
      } catch (e) { /* 没声明 inject 时这里会抛，忽略 */ }
      return null
    }

    /* 最后的兜底：投喂条没挂上时，会话 id 通常就在地址栏里（hash 或 query 里的 uuid）。 */
    function sessionIdFromLocation() {
      try {
        var hay = String(window.location.hash || '') + ' ' + String(window.location.search || '')
        var m = hay.match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i)
        if (m) return m[0]
      } catch (e) { /* 读不到地址栏就算了 */ }
      return ''
    }

    function envProbe(stage) {
      var ctx = clientCtx
      var out = {
        stage: String(stage),
        hasCtx: !!ctx,
        ctxSessions: false,
        ctxGet: !!(ctx && typeof ctx.get === 'function'),
        lookup: !!lookupSessions(),
        sessionId: store.state.sessionId || '',
        dock: !!dockMounted,
        items: store.state.items.length,
        picked: pickedItems().length
      }
      try { out.ctxSessions = !!(ctx && ctx.sessions) } catch (e) { out.ctxSessions = 'throw:' + ((e && e.message) || e) }
      if (ctx && typeof ctx.get === 'function') {
        try { out.getResult = ctx.get('sessions') ? 'ok' : 'null' } catch (e) { out.getResult = 'err:' + ((e && e.message) || e) }
      }
      var svc = lookupSessions()
      if (svc) {
        try { out.api = Object.keys(svc).join(',') } catch (e) { out.api = 'err:' + ((e && e.message) || e) }
      }
      return diag('env', out)
    }

    function normalizeItem(raw) {
      var it = raw || {}
      var tag = validTag(migrateTag(it.tag)) ? migrateTag(it.tag) : TAGS[0].key
      var qty = num(it.qty)
      var pick = clamp(num(it.pick), 0, qty)
      return {
        id: String(it.id || uid('it')),
        name: String(it.name || (it.displayName || '素材')),
        displayName: String(it.displayName || stripExt(it.name) || '素材'),
        tag: tag,
        tagFrom: it.tagFrom === 'shelf' ? 'shelf' : (it.tagFrom === 'manual' ? 'manual' : 'name'),
        brand: it.brand ? String(it.brand) : '',
        category: it.category ? String(it.category) : '',
        spec: it.spec && it.spec.label ? { label: String(it.spec.label), kind: String(it.spec.kind || 'other'), value: Number(it.spec.value) || 0 } : null,
        price: num(it.price),
        qty: qty,
        pick: pick,
        order: num(it.order),
        createdAt: num(it.createdAt) || Date.now(),
        w: num(it.w),
        h: num(it.h),
        alpha: !!it.alpha,
        gif: !!it.gif,
        origin: it.origin ? String(it.origin) : '',
        leaving: false
      }
    }

    function loadMeta() {
      var raw = null
      try { raw = localStorage.getItem(META_KEY) } catch (e) { raw = null }
      var meta = null
      if (raw) { try { meta = JSON.parse(raw) } catch (e) { meta = null } }
      if (!meta || typeof meta !== 'object') {
        store.set({ ready: true })
        return
      }
      var items = Array.isArray(meta.items) ? meta.items.filter(function (it) { return it && it.id }).map(normalizeItem) : []
      /* 1.5.2：老存档里的旧标签名（米饭/炒菜/炖菜/炖汤）就地改名。 */
      if (meta.tab) meta.tab = migrateTag(meta.tab)
      if (meta.lastTag) meta.lastTag = migrateTag(meta.lastTag)
      var dicts = {
        brand: Array.isArray(meta.dicts && meta.dicts.brand) ? meta.dicts.brand.slice(0, 300) : [],
        category: Array.isArray(meta.dicts && meta.dicts.category) ? meta.dicts.category.slice(0, 300) : [],
        spec: Array.isArray(meta.dicts && meta.dicts.spec) ? meta.dicts.spec.slice(0, 300) : []
      }
      var wallet = {
        spent: num(meta.wallet && meta.wallet.spent),
        bought: num(meta.wallet && meta.wallet.bought),
        history: Array.isArray(meta.wallet && meta.wallet.history) ? meta.wallet.history.slice(-12) : []
      }
      var arrange = 'default'
      for (var i = 0; i < ARRANGES.length; i++) if (ARRANGES[i].key === meta.arrange) arrange = meta.arrange
      var skin = meta.skin && typeof meta.skin === 'object' ? meta.skin : null
      /* 1.5.0：标签归属覆盖与话术覆盖都按「字符串 → 字符串」白名单收，脏数据一律丢掉。 */
      var groupMap = {}
      if (meta.groupMap && typeof meta.groupMap === 'object') {
        Object.keys(meta.groupMap).forEach(function (tag) {
          var k = migrateTag(tag)
          if (validTag(k) && groupMeta(meta.groupMap[tag])) groupMap[k] = String(meta.groupMap[tag])
        })
      }
      var sentences = {}
      if (meta.sentences && typeof meta.sentences === 'object') {
        Object.keys(meta.sentences).forEach(function (tag) {
          var k = migrateTag(tag)
          var row = meta.sentences[tag]
          if (validTag(k) && typeof row === 'string' && row.trim() && row.indexOf('{items}') !== -1) sentences[k] = row.slice(0, 240)
        })
      }
      /* 1.5.2：判定规则：每个标签一组字眼（去重、去空、最多 60 个），缺的标签用默认。 */
      var rules = defaultRules()
      if (meta.rules && typeof meta.rules === 'object') {
        Object.keys(meta.rules).forEach(function (tag) {
          var k = migrateTag(tag)
          if (!validTag(k)) return
          var arr = meta.rules[tag]
          if (!Array.isArray(arr)) return
          var seen = {}
          var out = []
          arr.forEach(function (w) {
            var word = String(w || '').trim().slice(0, 12)
            if (!word || seen[word] || out.length >= 60) return
            seen[word] = 1
            out.push(word)
          })
          rules[k] = out
        })
      }
      /* 1.6.0：新加的标签（糕点 / 套餐）在旧存档里没有字眼，这里补上默认值。 */
      Object.keys(DEFAULT_RULES).forEach(function (k) {
        if (!Object.prototype.hasOwnProperty.call(rules, k)) rules[k] = DEFAULT_RULES[k].slice()
      })
      var lastTag = validTag(meta.lastTag) ? meta.lastTag : (validTag(meta.tab) ? meta.tab : TAGS[0].key)
      store.set({
        items: items,
        tab: validTag(meta.tab) || meta.tab === OVERVIEW ? meta.tab : TAGS[0].key,
        lastTag: lastTag,
        arrange: arrange,
        priceDir: num(meta.priceDir) < 0 ? -1 : 1,
        feedThumb: !!meta.feedThumb,
        mute: !!meta.mute,
        /* 1.6.8：标签默认价格，只收 0–99999 的整数，且必须是认识的标签。 */
        priceMap: (function () {
          var out = {}
          if (meta.priceMap && typeof meta.priceMap === 'object') {
            Object.keys(meta.priceMap).forEach(function (tag) {
              var k = migrateTag(tag)
              if (!validTag(k)) return
              var v = num(meta.priceMap[tag])
              if (v >= 0 && v <= 99999) out[k] = v
            })
          }
          return out
        })(),
        /* 1.7.0 */
        balance: Math.max(0, num(meta.balance)),
        coupons: {
          yuan: Math.max(0, num(meta.coupons && meta.coupons.yuan)),
          round: Math.max(0, num(meta.coupons && meta.coupons.round))
        },
        dipUntil: num(meta.dipUntil),
        dipLeft: num(meta.dipLeft),
        dipTotal: num(meta.dipTotal),
        dipApplied: num(meta.dipApplied),
        dipStart: num(meta.dipStart),
        dipDur: num(meta.dipDur) || ROUND_DIP_MS,
        devMode: !!meta.devMode,
      devUnlocked: !!meta.devUnlocked,
        cardScale: CARD_SCALES[meta.cardScale] ? meta.cardScale : 'large',
      pickSeq: (meta.pickSeq && typeof meta.pickSeq === 'object') ? meta.pickSeq : {},
      pickTick: num(meta.pickTick),
        setMap: (meta.setMap && typeof meta.setMap === 'object') ? meta.setMap : {},
        groupDefs: Array.isArray(meta.groupDefs) && meta.groupDefs.length ? meta.groupDefs.filter(function (x) { return typeof x === 'string' && x.trim() }).slice(0, 12) : null,
        dicts: dicts,
        groupMap: groupMap,
        sentences: sentences,
        rules: rules,
        wallet: wallet,
        win: meta.win && typeof meta.win === 'object' ? meta.win : null,
        skin: {
          mode: skin && (skin.mode === 'color' || skin.mode === 'image') ? skin.mode : 'theme',
          color: skin && /^#[0-9a-fA-F]{6}$/.test(String(skin.color)) ? String(skin.color) : '#fff7e6',
          image: null
        },
        fontScale: clamp(flt(meta.fontScale, 1) || 1, 0.8, 1.6),
        ready: true
      })
    }

    var imagesLoading = false

    function loadImages() {
      if (imagesLoading || store.state.loadedImages) return
      imagesLoading = true
      idbAll().then(function (rows) {
        var images = {}
        Object.keys(rows || {}).forEach(function (key) {
          if (key.indexOf('img:') !== 0) return
          var id = key.slice(4)
          if (typeof rows[key] === 'string') images[id] = rows[key]
        })
        var skin = store.state.skin || {}
        var bg = rows && typeof rows.bg === 'string' ? rows.bg : null
        var sounds = Object.assign({}, store.state.sounds || {})
        Object.keys(SOUND_KEYS).forEach(function (k) {
          var got = rows && rows[SOUND_KEYS[k]]
          if (typeof got === 'string' && got) sounds[k] = got
        })
        store.set({
          images: Object.assign({}, images, store.state.images),
          skin: Object.assign({}, skin, { image: bg }),
          sounds: sounds,
          loadedImages: true
        })
      }).catch(function (e) {
        console.warn('[feiyu-lunchbox] 缩略图读取失败', e)
        store.set({ loadedImages: true })
      })
    }

    /* ------------------------------------------------------------ 文件名解析 */

    function wordsOf(kind) {
      var dict = store.state.dicts[kind] || []
      var base = kind === 'brand' ? BRAND_WORDS : kind === 'category' ? CATEGORY_WORDS : []
      return dict.concat(base).filter(Boolean)
    }

    function findLongest(text, words) {
      var best = ''
      for (var i = 0; i < words.length; i++) {
        var w = words[i]
        if (!w) continue
        if (text.indexOf(w) !== -1 && w.length > best.length) best = w
      }
      return best
    }

    /* 词尾优先：一个文件名里常常同时出现味道和品类（「咖啡威化饼」= 咖啡味的威化饼），
       所以取「离文件名末尾最近」的字眼，而不是按表里的顺序先到先得。
       分数相同（同一位置）时取更长的词：「葡萄」优于「果」、「海带」优于「带」。
       规则由「设置 → 判定规则」维护；1.6.7 起【特殊】也在里面（默认字眼「宝石」）。 */
    function ruleList() {
      var rules = store.state.rules || {}
      var list = []
      TAGS.forEach(function (t) {
        var words = Array.isArray(rules[t.key]) ? rules[t.key] : (DEFAULT_RULES[t.key] || [])
        list.push({ tag: t.key, words: words })
      })
      return list
    }

    function inferTag(filename) {
      var base = stripExt(filename)
      var table = ruleList()
      var best = null
      for (var i = 0; i < table.length; i++) {
        var entry = table[i]
        for (var j = 0; j < entry.words.length; j++) {
          var w = entry.words[j]
          if (!w) continue
          var at = base.lastIndexOf(w)
          if (at < 0) continue
          var score = at + w.length
          if (!best || score > best.score || (score === best.score && w.length > best.len)) {
            best = { tag: entry.tag, score: score, len: w.length, word: w }
          }
        }
      }
      return best ? best.tag : null
    }

    function matchSpec(text) {
      var m = text.match(/(\d+(?:\.\d+)?)\s*(ml|毫升|mL|ML|L|升|g|克|kg|KG|千克)/)
      if (m) {
        var raw = parseFloat(m[1])
        var unit = m[2].toLowerCase()
        var label
        var value
        if (unit === 'ml' || unit === '毫升') { label = raw + 'ml'; value = raw }
        else if (unit === 'l' || unit === '升') { label = raw + 'L'; value = raw * 1000 }
        else if (unit === 'g' || unit === '克') { label = raw + 'g'; value = raw }
        else { label = raw + 'kg'; value = raw * 1000 }
        return { label: label, kind: 'measure', value: value }
      }
      for (var i = 0; i < SIZE_WORDS.length; i++) {
        if (text.indexOf(SIZE_WORDS[i].word) !== -1) {
          return { label: SIZE_WORDS[i].word, kind: 'size', value: SIZE_WORDS[i].rank * 100 }
        }
      }
      var c = text.match(/(\d+)\s*(份|个|只|片|块|碗|杯|瓶|罐|袋|盒|串)/)
      if (c) return { label: c[1] + c[2], kind: 'count', value: parseInt(c[1], 10) }
      return null
    }

    function parseName(filename) {
      var base = stripExt(filename)
      var brand = findLongest(base, wordsOf('brand'))
      var rest = base
      if (brand) rest = base.split(brand).join(' ')
      var category = findLongest(rest, wordsOf('category'))
      if (!category) {
        var m1 = rest.match(/([\u4e00-\u9fa5]{1,3}味)/)
        if (m1) category = m1[1]
      }
      if (!category) {
        var m2 = rest.match(/([\u4e00-\u9fa5]{2,3}性)/)
        if (m2) category = m2[1]
      }
      if (category && category === brand) category = ''
      var spec = matchSpec(rest) || matchSpec(base)
      return { brand: brand || '', category: category || '', spec: spec }
    }

    /* -------------------------------------------------------------- 拖图缩略 */

    function makeThumb(file) {
      return new Promise(function (resolve) {
        var MAX = 560
        /* PNG / WebP / GIF / SVG 可能是带透明通道的素材：不能铺白底，也不能转 JPEG，
           否则透明区域会被烧成白色。这类一律原样输出 PNG，缩略图下面再垫一层
           棋盘格（CSS .flb-thumb-alpha），看得见哪里是透明的。 */
        /* 1.7.11：GIF 要保留原始字节，一旦过 canvas 就只剩第一帧，动画没了。 */
      var isGif = /^image\/gif$/i.test(String((file && file.type) || '')) ||
        (/\.gif$/i.test(String((file && file.name) || '')) && !/^image\//i.test(String((file && file.type) || 'image/gif')))
      var keepAlpha = /png|webp|gif|svg/i.test(String((file && file.type) || ''))
        var reader = new FileReader()
        reader.onerror = function () { resolve(null) }
        reader.onload = function () {
          var img = new Image()
          img.onerror = function () { resolve(null) }
          img.onload = function () {
            try {
              var w = img.naturalWidth || img.width
              var hgt = img.naturalHeight || img.height
              if (!w || !hgt) { resolve(null); return }
              /* 1.7.11：动图（GIF）原样存，<img> 自己会播。canvas 只能画第一帧。 */
              if (isGif) {
                resolve({ url: String(reader.result), w: w, h: hgt, alpha: false, gif: true })
                return
              }
              var scale = Math.min(1, MAX / Math.max(w, hgt))
              var cw = Math.max(1, Math.round(w * scale))
              var ch = Math.max(1, Math.round(hgt * scale))
              var canvas = document.createElement('canvas')
              canvas.width = cw
              canvas.height = ch
              var g = canvas.getContext('2d')
              if (!keepAlpha) {
                g.fillStyle = '#ffffff'
                g.fillRect(0, 0, cw, ch)
              }
              g.drawImage(img, 0, 0, cw, ch)
              var hasAlpha = keepAlpha && detectAlpha(g, cw, ch)
              resolve({
                url: hasAlpha ? canvas.toDataURL('image/png') : canvas.toDataURL('image/jpeg', 0.85),
                w: w, h: hgt, alpha: hasAlpha
              })
            } catch (e) { resolve(null) }
          }
          img.src = reader.result
        }
        reader.readAsDataURL(file)
      })
    }

    /* 真的扫一遍像素再决定：有些 .png 其实是不透明的，转 JPEG 反而更小。 */
    function detectAlpha(g, w, hgt) {
      try {
        var stepX = Math.max(1, Math.floor(w / 48))
        var stepY = Math.max(1, Math.floor(hgt / 48))
        for (var y = 0; y < hgt; y += stepY) {
          for (var x = 0; x < w; x += stepX) {
            var d = g.getImageData(x, y, 1, 1).data
            if (d[3] < 250) return true
          }
        }
      } catch (err) { /* 拿不到像素就当不透明 */ }
      return false
    }

    /* ------------------------------------------------------------ 示例素材图 */

    function sampleSvg(tag) {
      var meta = tagMeta(tag)
      var paths = ICON_PATHS[tag] || ICON_PATHS['特殊']
      var body = paths.map(function (d) { return '<path d="' + d + '"/>' }).join('')
      var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="480" height="360" viewBox="0 0 480 360">' +
        '<rect width="480" height="360" fill="#fff8e8"/>' +
        '<circle cx="240" cy="178" r="118" fill="' + meta.color + '" opacity="0.14"/>' +
        '<g transform="translate(144 82) scale(8)" fill="none" stroke="' + meta.color +
        '" stroke-width="1.35" stroke-linecap="round" stroke-linejoin="round">' + body + '</g>' +
        '<text x="240" y="330" text-anchor="middle" font-family="Segoe UI, Microsoft YaHei, sans-serif" ' +
        'font-size="30" font-weight="700" fill="' + meta.color + '">' + tag + '</text>' +
        '</svg>'
      return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg)
    }

    /* ---------------------------------------------------------------- 提示条 */

    var flashTimer = null

    function flash(text, tone) {
      if (flashTimer) clearTimeout(flashTimer)
      store.set({ note: { text: text, tone: tone || 'ok', at: Date.now() } })
      flashTimer = setTimeout(function () {
        flashTimer = null
        store.set({ note: null })
      }, 3600)
    }

    /* ------------------------------------------------------------ 音效 */

    /* 默认音效：叮（选中一件）= 两声高音；收银（投喂成功）= 三声上行 + 一点噪声味。 */
    function beepSound(kind) {
      /* 1.7.19：静音开关一开，连合成音也不响。 */
      if (store.state.mute) return
      try {
        var Ctor = (typeof window !== 'undefined') && (window.AudioContext || window.webkitAudioContext)
        if (!Ctor) return
        if (!beepSound.ctx) beepSound.ctx = new Ctor()
        var ac = beepSound.ctx
        if (ac.state === 'suspended' && ac.resume) { try { ac.resume() } catch (e) {} }
        var t0 = ac.currentTime
        function tone(freq, at, dur, gain, type) {
          var o = ac.createOscillator()
          var g = ac.createGain()
          o.type = type || 'sine'
          o.frequency.setValueAtTime(freq, t0 + at)
          g.gain.setValueAtTime(0.0001, t0 + at)
          g.gain.exponentialRampToValueAtTime(gain, t0 + at + 0.012)
          g.gain.exponentialRampToValueAtTime(0.0001, t0 + at + dur)
          o.connect(g)
          g.connect(ac.destination)
          o.start(t0 + at)
          o.stop(t0 + at + dur + 0.03)
        }
        if (kind === 'dingLoud') {
          /* 1.7.0：蓝绿修改器那一下，比普通叮响一档。 */
          tone(1568, 0, 0.16, 0.3, 'sine')
          tone(2093, 0.06, 0.34, 0.22, 'sine')
          tone(2637, 0.14, 0.4, 0.12, 'sine')
          return
        }
        if (kind === 'dice') {
          /* 1.6.3：骰子落桌的「嗒嗒嗒」——三颗短点 + 一点尾巴。 */
          tone(880, 0, 0.05, 0.14, 'square')
          tone(1180, 0.07, 0.05, 0.13, 'square')
          tone(760, 0.14, 0.06, 0.12, 'square')
          tone(1560, 0.22, 0.12, 0.08, 'sine')
          return
        }
        if (kind === 'cash') {
          tone(1046.5, 0, 0.14, 0.16, 'triangle')
          tone(1568, 0.09, 0.18, 0.15, 'triangle')
          tone(2093, 0.19, 0.3, 0.11, 'sine')
        } else {
          tone(1568, 0, 0.12, 0.17, 'sine')
          tone(2093, 0.05, 0.2, 0.1, 'sine')
        }
      } catch (err) { /* 没声音也要照常干活 */ }
    }

    /* 1.7.1：内嵌的成就音不再用 <audio src="data:...">（页面 CSP 会拦掉 data: 媒体，表现就是没声音），
       改成音乐上下文解码后播放：decodeAudioData 不受 media-src 限制，解码一次会缓存。 */
    var bankBuffers = {}
    function bankCtx () {
      try {
        var Ctor = (typeof window !== 'undefined') && (window.AudioContext || window.webkitAudioContext)
        if (!Ctor) return null
        if (!beepSound.ctx) beepSound.ctx = new Ctor()
        var ac = beepSound.ctx
        if (ac.state === 'suspended' && ac.resume) { try { ac.resume() } catch (e) {} }
        return ac
      } catch (e) { return null }
    }
    function bankBytes (url) {
      var b64 = String(url).split(',')[1] || ''
      var bin = ''
      try { bin = atob(b64) } catch (e) { return null }
      var bytes = new Uint8Array(bin.length)
      for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
      return bytes.buffer
    }
    function fireBuffer (buf) {
      try {
        var ac = bankCtx()
        if (!ac) return
        var src = ac.createBufferSource()
        var g = ac.createGain()
        g.gain.value = 0.9
        src.buffer = buf
        src.connect(g)
        g.connect(ac.destination)
        src.start(0)
      } catch (e) {}
    }
    function playBank (key) {
      if (store.state.mute) return false
      try {
        var url = SOUND_BANK[key]
        if (!url) return false
        if (bankBuffers[key]) { fireBuffer(bankBuffers[key]); return true }
        var ac = bankCtx()
        if (!ac) return false
        var bytes = bankBytes(url)
        if (!bytes) return false
        var ok = false
        ac.decodeAudioData(bytes, function (buf) {
          bankBuffers[key] = buf
          fireBuffer(buf)
        }, function () { beepSound('cash') })
        ok = true
        return ok
      } catch (e) { return false }
    }

    var lastSoundKind = ''
    function playSound(kind) {
      /* 1.7.10：记下最近一次音效，测试与开发者测试都用得上。 */
      lastSoundKind = kind || ''
      /* 1.7.19（需求）：静音时直接返回，什么都不放。 */
      if (store.state.mute) return
      var key = kind === 'cash' ? 'cash' : 'ding'
      if (kind === 'dice') { beepSound('dice'); return }
      if (kind === 'dingLoud') { beepSound('dingLoud'); return }
      if (kind === 'ps5' || kind === 'stardew' || kind === 'mc') {
        /* 1.7.6：先看用户上传的成就音，没有才放内嵌的那三首 */
        var own = (store.state.sounds || {})[kind]
        if (own && typeof Audio !== 'undefined') {
          try {
            var a2 = new Audio(own)
            a2.volume = 0.95
            var pr = a2.play()
            if (pr && pr.catch) pr.catch(function () {})
            return
          } catch (e2) { /* 落到内嵌音 */ }
        }
        if (playBank(kind)) return
        beepSound('cash')
        return
      }
      try {
        var url = (store.state.sounds || {})[key]
        if (url && typeof Audio !== 'undefined') {
          var audio = new Audio(url)
          audio.volume = 0.9
          var played = audio.play()
          if (played && played.catch) played.catch(function () {})
          return
        }
        beepSound(key)
      } catch (err) { /* 同上 */ }
    }

    /* 1.7.19（需求）：静音开关，存在 meta 里，刷新后还记得。 */
    function setMute(on) {
      store.set({ mute: !!on })
      saveMeta()
      if (!on) {
        /* 取消静音时给一声轻的「叮」，让人知道声音回来了。 */
        setTimeout(function () { playSound('ding') }, 30)
      }
    }

    function setSound(kind, url) {
      /* 1.7.6：五种音效（叮 / 收银 / 三档成就音）都能存 */
      var key = SOUND_KEYS[kind] ? kind : 'ding'
      var next = Object.assign({}, store.state.sounds || {})
      next[key] = url || null
      store.set({ sounds: next })
      /* 存取失败（没有 IndexedDB、配额满）不打断界面：音效只在这一台机器上记住。 */
      if (url) idbPut(SOUND_KEYS[key], url).catch(function () {})
      else idbDelete(SOUND_KEYS[key]).catch(function () {})
    }

    /* ------------------------------------------------------------ 换肤 / 字号 */

    /* 皮肤三种：跟主题（默认）、纯色（色盘里挑）、背景图（自己上传）。
       背景图存 IndexedDB 的 bg 键，meta 里只留 mode/color，避免 localStorage 被图撑爆。 */
    var SKIN_PRESETS = ['#fff7e6', '#f4f7fb', '#eef7f0', '#fdf2f8', '#f3f0ff', '#fff1f1', '#1f2430', '#2b2118']

    function setSkinColor(color) {
      var hex = String(color || '')
      if (!/^#[0-9a-fA-F]{6}$/.test(hex)) return
      store.set({ skin: Object.assign({}, store.state.skin, { mode: 'color', color: hex }) })
      saveMeta()
    }

    function setSkinMode(mode) {
      var m = mode === 'image' || mode === 'color' ? mode : 'theme'
      store.set({ skin: Object.assign({}, store.state.skin, { mode: m }) })
      saveMeta()
      if (m === 'image' && !store.state.skin.image) flash('先点「上传背景图」挑一张，图会存本机', 'ok')
    }

    function setSkinImage(file) {
      if (!file) return
      if (!/^image\//.test(file.type || '')) { flash('背景图得是图片文件', 'err'); return }
      var reader = new FileReader()
      reader.onerror = function () { flash('这张图读不出来', 'err') }
      reader.onload = function () {
        var raw = String(reader.result || '')
        var img = new Image()
        img.onerror = function () { flash('这张图打不开，换一张试试', 'err') }
        img.onload = function () {
          try {
            /* 背景图只留到 1600px 宽，存 PNG/JPEG 都行，太大只会拖慢打开窗口。 */
            var MAX = 1600
            var scale = Math.min(1, MAX / Math.max(img.naturalWidth || img.width, img.naturalHeight || img.height))
            var cw = Math.max(1, Math.round((img.naturalWidth || img.width) * scale))
            var ch = Math.max(1, Math.round((img.naturalHeight || img.height) * scale))
            var canvas = document.createElement('canvas')
            canvas.width = cw
            canvas.height = ch
            var g = canvas.getContext('2d')
            g.drawImage(img, 0, 0, cw, ch)
            var url = canvas.toDataURL('image/jpeg', 0.86)
            idbPut('bg', url).catch(function () {})
            store.set({ skin: Object.assign({}, store.state.skin, { mode: 'image', image: url }) })
            saveMeta()
            flash('背景图换好了', 'ok')
          } catch (e) { flash('这张图处理不了：' + e.message, 'err') }
        }
        img.src = raw
      }
      reader.readAsDataURL(file)
    }

    function clearSkin() {
      try { idbDelete('bg').catch(function () {}) } catch (e) { /* 没 IndexedDB 就算了 */ }
      store.set({ skin: { mode: 'theme', color: '#fff7e6', image: null } })
      saveMeta()
      flash('换回默认皮肤', 'ok')
    }

    function setFontScale(next) {
      var v = clamp(Math.round(flt(next, 1) * 10) / 10, 0.8, 1.6)
      store.set({ fontScale: v })
      saveMeta()
    }

    /* 整窗背景：mode=theme 时返回 null，让 CSS 主题色生效。 */
    function skinStyle(skin) {
      var s = skin || {}
      if (s.mode === 'color') return { '--flb-skin': s.color, '--flb-skin-image': 'none' }
      if (s.mode === 'image' && s.image) return { '--flb-skin-image': 'url("' + s.image + '")' }
      return null
    }

    /* ------------------------------------------------------------ 进货 / 换货 */

    var addSeq = 0

    function nextOrder(items) {
      var max = 0
      for (var i = 0; i < items.length; i++) if (items[i].order > max) max = items[i].order
      return max + 1
    }

    /* 1.6.8：「标签映射」里设的默认价格；没设过就 DEFAULT_PRICE。 */
    function defaultPriceOf(tag) {
      var map = store.state.priceMap || {}
      if (!Object.prototype.hasOwnProperty.call(map, tag)) return DEFAULT_PRICE
      var v = num(map[tag])
      return v >= 0 && v <= 99999 ? v : DEFAULT_PRICE
    }

    function setTagPrice(tag, value) {
      if (!validTag(tag)) return
      var next = Object.assign({}, store.state.priceMap || {})
      var v = Math.max(0, Math.min(99999, num(value)))
      if (v === DEFAULT_PRICE) delete next[tag]
      else next[tag] = v
      store.set({ priceMap: next })
      saveMeta()
      flash('「' + tag + '」的默认价格：' + defaultPriceOf(tag) + ' 元', 'ok')
    }

    function makeItem(fields) {
      var base = {
        id: uid('it'),
        name: '',
        displayName: '',
        tag: TAGS[0].key,
        tagFrom: 'name',
        brand: '',
        category: '',
        spec: null,
        price: defaultPriceOf((fields && fields.tag) || TAGS[0].key),
        qty: DEFAULT_STOCK,
        pick: 0,
        order: 0,
        createdAt: Date.now(),
        w: 0,
        h: 0,
        origin: '',
        leaving: false
      }
      return Object.assign(base, fields || {})
    }

    function addFiles(fileList, opts) {
      opts = opts || {}
      var files = []
      for (var i = 0; i < fileList.length; i++) {
        var f = fileList[i]
        if (f && /^image\//.test(f.type || '')) files.push(f)
      }
      if (!files.length) {
        flash('这些不是图片，货架只收图片素材', 'err')
        return
      }
      var fallbackTag = validTag(opts.tag) ? opts.tag : activeTag()
      var lastTag = null
      var failed = 0
      var chain = Promise.resolve()
      files.forEach(function (file) {
        chain = chain.then(function () {
          var tag = inferTag(file.name)
          var tagFrom = tag ? 'name' : 'shelf'
          var finalTag = tag || fallbackTag
          var parsed = parseName(file.name)
          /* makeThumb 在极端情况下会同步抛（比如没有 FileReader），包成 Promise 拒绝，
             这样下面的失败分支能兜住，而不是把整条进货链断掉。 */
          return Promise.resolve().then(function () { return makeThumb(file) }).then(function (thumb) {
            var st = store.state
            var item = makeItem({
              name: file.name,
              displayName: stripExt(file.name) || ('素材' + (++addSeq)),
              tag: finalTag,
              tagFrom: tagFrom,
              brand: parsed.brand,
              category: parsed.category,
              spec: parsed.spec,
              /* 1.5.0：记下它从哪个文件夹 / 压缩包路径来的，右键提示里能查到。 */
              origin: (opts.origins && opts.origins[file.name]) || '',
              order: nextOrder(st.items)
            })
            var images = Object.assign({}, st.images)
            if (thumb) images[item.id] = thumb.url
            item.w = thumb ? thumb.w : 0
            item.h = thumb ? thumb.h : 0
            /* 带透明通道的素材：缩略图下面垫棋盘格，一眼看得出哪里是透明的。 */
            item.alpha = !!(thumb && thumb.alpha)
            /* 1.7.11：动图标记，缩略图 title 里会写一句。 */
            item.gif = !!(thumb && thumb.gif)
            store.set({ items: st.items.concat([item]), images: images })
            if (thumb) idbPut('img:' + item.id, thumb.url).catch(function () {})
            lastTag = finalTag
            saveMeta()
          }, function () { failed++ })
        })
      })
      chain.then(function () {
        var ok = files.length - failed
        /* 在总览页进货就留在总览页；在单页进货才跟着跳到素材归的那一页。 */
        if (lastTag && !isOverview(store.state.tab)) store.set({ tab: lastTag, lastTag: lastTag })
        if (!ok) { flash('这些图片读不出来（格式或权限问题）', 'err') }
        else flash('进货 ' + ok + ' 件' + (failed ? '，' + failed + ' 件没读出来' : '') + '，已码上货架', 'ok')
      })
    }

    function addSample(tag) {
      var st = store.state
      var count = 0
      st.items.forEach(function (it) { if (it.tag === tag) count++ })
      var name = tag + (count ? String(count + 1) : '') + '.png'
      var item = makeItem({
        name: name,
        displayName: tag + (count ? String(count + 1) : ''),
        tag: tag,
        tagFrom: 'name',
        spec: null,
        order: nextOrder(st.items)
      })
      var url = sampleSvg(tag)
      item.w = 480
      item.h = 360
      var images = Object.assign({}, st.images)
      images[item.id] = url
      store.set({ items: st.items.concat([item]), images: images, tab: tag })
      idbPut('img:' + item.id, url).catch(function () {})
      saveMeta()
      flash('放了一件「' + tag + '」示例，可继续拖图进货', 'ok')
    }

    function updateItem(id, patch) {
      var st = store.state
      var items = st.items.map(function (it) {
        if (it.id !== id) return it
        var next = Object.assign({}, it, patch)
        next.pick = clamp(num(next.pick), 0, MAX_PICK)
        next.price = num(next.price)
        next.qty = num(next.qty)
        return next
      })
      store.set({ items: items })
      saveMeta()
      /* 1.5.2 需求④：改标价 / 改数量（输入框的增减）也响「选中商品」。 */
      if (patch && (patch.price !== undefined || patch.qty !== undefined)) playSound('ding')
    }

    /* 1.5.0 追加：识别错标签时手动改归——只动 tag 与 tagFrom，其它字段不碰。 */
    function setItemTag(id, tag) {
      if (!validTag(tag)) return
      var st = store.state
      var items = st.items.map(function (it) {
        if (it.id !== id) return it
        var next = Object.assign({}, it, { tag: tag, tagFrom: 'manual' })
        return next
      })
      store.set({ items: items })
      saveMeta()
      flash('已手动归到「' + tag + '」货架', 'ok')
    }

    function setPick(id, value) {
      var st = store.state
      var before = 0
      var after = 0
      var items = st.items.map(function (it) {
        if (it.id !== id) return it
        before = num(it.pick)
        var next = Object.assign({}, it)
        next.pick = clamp(num(value), 0, MAX_PICK)
        after = next.pick
        return next
      })
      /* 1.7.9：从 0 变成有份数时记下它是第几个点的；取消到 0 就把记号删掉。 */
      var seq = Object.assign({}, st.pickSeq || {})
      var tick = num(st.pickTick)
      if (before === 0 && after > 0) { tick += 1; seq[id] = tick }
      if (after === 0) delete seq[id]
      store.set({ items: items, pickSeq: seq, pickTick: tick })
      saveMeta()
      /* 1.5.2 需求④：点菜的加、减，以及托盘里取消选购，都要「叮」一下。 */
      if (after !== before) playSound('ding')
    }

    function togglePick(id) {
      var st = store.state
      var target = null
      st.items.forEach(function (it) { if (it.id === id) target = it })
      if (!target) return
      setPick(id, target.pick > 0 ? 0 : 1)
    }

    function removeItems(ids, animate) {
      if (!ids || !ids.length) return
      var idMap = {}
      ids.forEach(function (id) { idMap[id] = true })
      var st = store.state

      function finalize() {
        var cur = store.state
        var images = Object.assign({}, cur.images)
        var keep = []
        cur.items.forEach(function (it) {
          if (idMap[it.id] && it.leaving) {
            delete images[it.id]
            idbDelete('img:' + it.id).catch(function () {})
          } else keep.push(it)
        })
        store.set({ items: keep, images: images })
        clearPickSeq(true)
        saveMeta()
      }

      if (!animate) {
        store.set({ items: st.items.filter(function (it) { return !idMap[it.id] }) })
        clearPickSeq(true)
        var images = Object.assign({}, st.images)
        ids.forEach(function (id) {
          delete images[id]
          idbDelete('img:' + id).catch(function () {})
        })
        store.set({ images: images })
        saveMeta()
        return
      }

      store.set({
        items: st.items.map(function (it) {
          return idMap[it.id] ? Object.assign({}, it, { leaving: true, pick: 0 }) : it
        })
      })
      setTimeout(finalize, 520)
      saveMeta()
    }

    function clearSelected() {
      /* 1.4.0：换货只认右上角勾选的货，不再和「点菜」抢同一个选中状态。 */
      var ids = markedItems().map(function (it) { return it.id })
      if (!ids.length) { flash('先点素材右上角的小方框，勾中要换掉的货', 'err'); return }
      removeItems(ids, true)
      var marked = Object.assign({}, store.state.marked)
      ids.forEach(function (id) { delete marked[id] })
      store.set({ confirmClear: false, marked: marked })
      /* 1.7.12（需求①）：说法改成「下架」。清理多件时才带数量。 */
      flash(ids.length > 1 ? ids.length + ' 件商品下架了' : '这件商品下架了', 'ok')
    }

    function resetWallet() {
      store.set({ wallet: { spent: 0, bought: 0, history: [] } })
      saveMeta()
      flash('钱包已清空：已投喂 0 元，重新开始记账', 'ok')
    }

    function clearShelf(tag) {
      var ids = []
      store.state.items.forEach(function (it) { if (it.tag === tag && !it.leaving) ids.push(it.id) })
      if (!ids.length) { flash('这一页本来就是空的', 'err'); return }
      removeItems(ids, true)
      flash('「' + tag + '」这一页清空了', 'ok')
    }

    /* 1.5.2：清空全部货架只管货，不碰钱——「已投喂」只能由「清空钱包」重置。 */
    function clearAll() {
      var ids = []
      store.state.items.forEach(function (it) { if (!it.leaving) ids.push(it.id) })
      removeItems(ids, false)
      store.set({ marked: {} })
      flash('所有货架已清空（钱包没动，要归零请点「清空钱包」）', 'ok')
    }

    /* ------------------------------------------------------------ 选货 / 结账 */

    function pickedItems(st) {
      st = st || store.state
      var seq = st.pickSeq || {}
      var list = st.items.filter(function (it) { return !it.leaving && it.pick > 0 })
      /* 1.7.9：按「点菜的先后」排——先点的在前，所以台词取的是最先点的那件。 */
      return list.slice().sort(function (a, b) {
        var sa = num(seq[a.id])
        var sb = num(seq[b.id])
        if (!sa && !sb) return num(a.order) - num(b.order)
        if (!sa) return 1
        if (!sb) return -1
        return sa - sb
      })
    }

    function totalsOf(list) {
      var qty = 0
      var tokens = 0
      list.forEach(function (it) {
        qty += num(it.pick)
        tokens += num(it.pick) * num(it.price)
      })
      return { qty: qty, tokens: tokens, count: list.length }
    }

    function groupOrder(list) {
      var seen = []
      list.forEach(function (it) {
        var g = groupOfTag(it.tag)
        if (seen.indexOf(g) === -1) seen.push(g)
      })
      return GROUPS.map(function (g) { return g.key }).filter(function (g) { return seen.indexOf(g) !== -1 })
    }

    function tagOrder(list) {
      var seen = []
      list.forEach(function (it) { if (seen.indexOf(it.tag) === -1) seen.push(it.tag) })
      return TAGS.map(function (t) { return t.key }).filter(function (k) { return seen.indexOf(k) !== -1 })
    }

    /* 1.5.0：对话文本可以在设置里改（每个标签一套），{items} 是占位符。 */
    function sentenceFor(tag) {
      var custom = (store.state.sentences || {})[tag]
      var def = TAG_SENTENCE[tag] || SENTENCE
      if (typeof custom === 'string' && custom.trim() && custom.indexOf('{items}') !== -1) return custom.trim()
      return def
    }

    function buildBatch() {
      var list = pickedItems()
      if (!list.length) return null
      /* 1.4.0：台词按标签区分（零食/饮料/果蔬/米面/煎炒/烧烤/蒸炖/糕点/套餐/特殊各一套）。
         1.5.5：不再加「【闲暇时光】」这类前缀 —— 对话里只要那句话本身。
         1.7.8：一次投喂多件（含整份套餐）不再按标签连发几句，只发一句——
         台词取排第一位那件商品的标签，商品用「+」串在同一个引号里。 */
      var names = list.map(function (it) {
        return it.displayName + '*' + it.pick
      }).join('+')
      var lines = [sentenceFor(list[0].tag).replace('{items}', names)]
      var totals = totalsOf(list)
      var batch = {
        v: 1,
        kind: 'feiyu-batch',
        items: list.map(function (it) {
          return {
            id: it.id, name: it.displayName, tag: it.tag,
            group: groupOfTag(it.tag), qty: it.pick, price: it.price
          }
        }),
        totals: { qty: totals.qty, tokens: totals.tokens },
        text: lines.join('\n')
      }
      lastBatch = batch
      return batch
    }

    /* ------------------------------------------------- 1.7.0 余额（鲸元） */

    function addBalance (n) {
      var v = Math.max(0, num(store.state.balance) + num(n))
      store.set({ balance: v })
      saveMeta()
      return v
    }

    function spendBalance (n) {
      var cost = Math.max(0, num(n))
      if (num(store.state.balance) < cost) return false
      store.set({ balance: num(store.state.balance) - cost })
      saveMeta()
      return true
    }

    function resetBalance () {
      store.set({
        balance: 0, coupons: { yuan: 0, round: 0 },
        dipUntil: 0, dipLeft: 0, dipTotal: 0, dipApplied: 0, dipStart: 0
      })
      saveMeta()
      playSound('cash')
      flash('余额已清空：0 鲸元，券也一起清掉了', 'ok')
    }

    /* 走完一圈 10 秒：＋1 鲸元，并掷一次券（5% 鲸元券 / 0.1% 鲸圆券）。 */
    function tickBalance () {
      addBalance(BALANCE_PER_TICK)
      var c = store.state.coupons || { yuan: 0, round: 0 }
      if (Math.random() < COUPON_ROUND_RATE) {
        store.set({ coupons: { yuan: num(c.yuan), round: num(c.round) + 1 } })
        saveMeta()
        /* 1.7.10：鲸圆券给「兑换」那记音效。 */
        playSound('dice')
        flash('🎉 掉了一张「鲸圆券」！去「兑换」兑成 1,000,000 鲸元', 'ok')
        return 'round'
      }
      if (Math.random() < COUPON_YUAN_RATE) {
        store.set({ coupons: { yuan: num(c.yuan) + 1, round: num(c.round) } })
        saveMeta()
        /* 1.7.10：鲸元券给「叮」。 */
        playSound('ding')
        return 'yuan'
      }
      return null
    }

    /* 贬值：60 秒里慢慢扣掉总量的 99%，按经过的时间等比例扣。 */
    /* 1.7.5：按「已过去多少毫秒 / 总时长」算应扣多少，再减已扣的。
       这样窗口卡顿、切后台再回来都不会漏扣或多扣。 */
    function dipStep () {
      var st = store.state
      var total = num(st.dipTotal)
      if (!total) {
        if (num(st.dipLeft) || num(st.dipUntil)) store.set({ dipUntil: 0, dipLeft: 0 })
        return 0
      }
      var dur = Math.max(1000, num(st.dipDur) || ROUND_DIP_MS)
      var start = num(st.dipStart) || Date.now()
      var passed = Math.min(dur, Math.max(0, Date.now() - start))
      var should = Math.round(total * passed / dur)
      var cut = Math.max(0, should - num(st.dipApplied))
      var left = Math.max(0, total - should)
      if (cut > 0) {
        store.set({
          balance: Math.max(0, num(st.balance) - cut),
          dipApplied: should,
          dipLeft: left,
          dipUntil: passed >= dur ? 0 : start + dur
        })
      }
      if (passed >= dur) {
        store.set({ dipTotal: 0, dipApplied: 0, dipStart: 0, dipLeft: 0, dipUntil: 0 })
        saveMeta()
      }
      return cut
    }

    /* 每秒扣多少（底栏红字用）：总量 ÷ 总秒数。 */
    function dipPerSec () {
      var st = store.state
      var total = num(st.dipTotal)
      if (!total) return 0
      return Math.max(1, Math.round(total / Math.max(1, (num(st.dipDur) || ROUND_DIP_MS) / 1000)))
    }

    function tierFor (r) {
      for (var i = 0; i < YUAN_TIERS.length; i++) {
        if (r < YUAN_TIERS[i].below) return YUAN_TIERS[i]
      }
      return YUAN_TIERS[YUAN_TIERS.length - 1]
    }

    /* 兑换鲸元券：一张一张按累计概率掷；兑到 5000 / 10000 / 114514 各有专属音效。 */
    function redeemYuan (count) {
      var c = store.state.coupons || { yuan: 0, round: 0 }
      var n = Math.min(num(count), num(c.yuan))
      if (!n) { flash('没有「鲸元券」可兑', 'err'); return 0 }
      var gained = 0
      var sound = null
      var best = 0
      for (var i = 0; i < n; i++) {
        var t = tierFor(Math.random())
        gained += t.amount
        if (t.amount > best) { best = t.amount; sound = t.sound || null }
      }
      store.set({
        coupons: { yuan: num(c.yuan) - n, round: num(c.round) },
        balance: num(store.state.balance) + gained
      })
      saveMeta()
      if (sound) playSound(sound)
      else playSound('dice')
      flash('兑了 ' + n + ' 张「鲸元券」→ +' + gained + ' 鲸元（最大一张 ' + best + '）', 'ok')
      return gained
    }

    /* 兑换鲸圆券：+1,000,000，然后 60 秒里按时间比例被扣掉 990,000（余额贬值中）。 */
    function redeemRound (count) {
      var c = store.state.coupons || { yuan: 0, round: 0 }
      var n = Math.min(num(count), num(c.round))
      if (!n) { flash('没有「鲸圆券」可兑', 'err'); return 0 }
      var gained = ROUND_BONUS * n
      var decay = Math.round(gained * ROUND_DIP_RATE)
      var st0 = store.state
      /* 多张一起兑 / 贬值还没走完又兑：把没扣完的量并进来一起算总值，重新走满 1 分钟。 */
      var keep = Math.max(0, num(st0.dipTotal) - num(st0.dipApplied))
      var total = keep + decay
      store.set({
        coupons: { yuan: num(c.yuan), round: num(c.round) - n },
        balance: num(st0.balance) + gained,
        dipTotal: total,
        dipApplied: 0,
        dipStart: Date.now(),
        dipDur: ROUND_DIP_MS,
        dipLeft: total,
        dipUntil: Date.now() + ROUND_DIP_MS
      })
      saveMeta()
      playSound('dice')
      flash('鲸圆券 +' + addDots(gained) + ' 鲸元……接下来 1 分钟连续贬值，共扣 ' + addDots(total), 'ok')
      return gained
    }

    /* 1.7.7：解锁 / 重新锁上开发者测试（锁上时顺手把测试面板收起来）。 */
    function setDevUnlocked (on) {
      store.set({ devUnlocked: !!on, devOpen: on ? store.state.devOpen : false })
      saveMeta()
      playSound('ding')
    }

    function setDevMode (on) {
      store.set({ devMode: !!on })
      saveMeta()
    }

    /* ------------------------------------------------- 1.7.0 标签组（可增删改） */

    function groupDefs () {
      var st = store.state
      if (Array.isArray(st.groupDefs) && st.groupDefs.length) return st.groupDefs.slice()
      return GROUPS.map(function (g) { return g.key })
    }

    function setGroupDefs (list) {
      var next = (list || []).map(function (x) { return String(x).trim().slice(0, 12) })
      next = next.filter(function (x, i) { return x && next.indexOf(x) === i }).slice(0, 12)
      if (!next.length) { flash('至少要留一个标签组', 'err'); return false }
      var defs = GROUPS.map(function (g) { return g.key })
      var isDefault = next.length === defs.length && next.every(function (x, i) { return x === defs[i] })
      store.set({ groupDefs: isDefault ? null : next })
      saveMeta()
      return true
    }

    function renameGroup (from, to) {
      var name = String(to || '').trim().slice(0, 12)
      if (!name) { flash('标签组名字不能是空的', 'err'); return false }
      if (name === from) return true
      var list = groupDefs()
      if (list.indexOf(name) !== -1) { flash('已经有叫「' + name + '」的标签组了', 'err'); return false }
      list = list.map(function (x) { return x === from ? name : x })
      var map = Object.assign({}, store.state.groupMap)
      Object.keys(map).forEach(function (tag) { if (map[tag] === from) map[tag] = name })
      var okSet = setGroupDefs(list)
      if (okSet) { store.set({ groupMap: map }); saveMeta() }
      flash('标签组「' + from + '」改名为「' + name + '」', 'ok')
      return okSet
    }

    function removeGroup (name) {
      var list = groupDefs().filter(function (x) { return x !== name })
      if (!list.length) { flash('至少要留一个标签组', 'err'); return false }
      var map = Object.assign({}, store.state.groupMap)
      Object.keys(map).forEach(function (tag) { if (map[tag] === name) delete map[tag] })
      setGroupDefs(list)
      store.set({ groupMap: map })
      saveMeta()
      flash('已删掉标签组「' + name + '」，原来归它的货回到默认组', 'ok')
      return true
    }

    function addGroup (name) {
      var n = String(name || '').trim().slice(0, 12)
      if (!n) { flash('先写一个标签组名字', 'err'); return false }
      var list = groupDefs()
      if (list.indexOf(n) !== -1) { flash('已经有叫「' + n + '」的标签组了', 'err'); return false }
      var okAdd = setGroupDefs(list.concat([n]))
      if (okAdd) flash('新增标签组「' + n + '」，把它挂到某个商品上即可', 'ok')
      return okAdd
    }

    /* 套餐随机：默认「特殊」不参加，标签映射里能单独打开。 */
    function inSets (tag) {
      var map = store.state.setMap || {}
      if (Object.prototype.hasOwnProperty.call(map, tag)) return !!map[tag]
      return tag !== '特殊'
    }

    function setInSets (tag, on) {
      var map = Object.assign({}, store.state.setMap || {})
      map[tag] = !!on
      store.set({ setMap: map })
      saveMeta()
    }

    function setCardScale (key) {
      if (!CARD_SCALES[key]) return
      store.set({ cardScale: key })
      saveMeta()
    }
    /* 1.7.9：清掉点菜记号（买完、清空、删除素材时用）。 */
    function clearPickSeq(keep) {
      var seq = {}
      var items = store.state.items
      Object.keys(store.state.pickSeq || {}).forEach(function (id) {
        var hit = items.filter(function (it) { return it.id === id })[0]
        if (hit && num(hit.pick) > 0) seq[id] = store.state.pickSeq[id]
      })
      if (!keep) seq = {}
      store.set({ pickSeq: seq })
    }

    function applyPurchase(payload) {
      var st = store.state
      var bought = {}
      ;(payload.items || []).forEach(function (row) {
        bought[row.id] = num(row.qty)
      })
      var items = st.items.map(function (it) {
        if (!bought[it.id]) return it
        var next = Object.assign({}, it)
        /* 1.6.0（需求②）：无限供应，投喂后不再扣「数量」。 */
        next.qty = MAX_PICK
        /* 买完就清空挑选：已经装进饭盒里的份数不再算在选择里。 */
        next.pick = 0
        return next
      })
      var tokens = num(payload.totals && payload.totals.tokens)
      var qty = num(payload.totals && payload.totals.qty)
      var wallet = {
        spent: num(st.wallet.spent) + tokens,
        bought: num(st.wallet.bought) + qty,
        history: (st.wallet.history || []).concat([{
          at: Date.now(),
          qty: qty,
          tokens: tokens,
          text: payload.text
        }]).slice(-12)
      }
      /* 1.7.0：投喂要花余额，花掉的记进「已投喂」。 */
      var left = Math.max(0, num(st.balance) - tokens)
      store.set({ items: items, wallet: wallet, balance: left })
      clearPickSeq(true)
      saveMeta()
      /* 需求④：一批投喂完成 = 收银。 */
      playSound('cash')
    }

    function reportFeedFail(message, stage, sessionId) {
      var err = new Error(message)
      err.stage = stage
      var at = Date.now()
      store.set({ lastError: { at: at, stage: stage, message: message } })
      /* 1.7.7：这行红字只留 6 秒，免得一直挂在投喂条下面妨碍阅读。 */
      setTimeout(function () {
        var cur = store.state.lastError
        if (cur && cur.at === at) store.set({ lastError: null })
      }, 6000)
      diag('feed-fail', {
        stage: stage,
        message: message,
        sessionId: sessionId || '',
        lookup: !!lookupSessions()
      })
      return err
    }

    /* 1.6.0（需求⑥）：开关打开时，除了那句话，再把这批货的缩略图一起发过去。
       图片走 prompt 的 image part：{ type:'image', mediaType, data: base64, name }。
       素材本身可能没有上传图（示例素材），那就跳过，只发文字。 */
    function feedParts(payload) {
      var parts = [{ type: 'text', text: payload.text }]
      if (!store.state.feedThumb) return parts
      var images = store.state.images || {}
      ;(payload.items || []).forEach(function (row) {
        var url = images[row.id]
        if (!url || String(url).indexOf('data:') !== 0) return
        var m = /^data:([^;]+);base64,(.+)$/.exec(String(url))
        if (!m) return
        /* 1.7.11：动图是原样存的，体积可能很大。超过 ~1MB 的图就不塞进对话了，
           不然一次投喂能把 token 吃光——文案里仍然有它的名字与份数。 */
        if (m[2].length > 1400000) {
          diag('feed-img-skip', { id: row.id, bytes: m[2].length })
          return
        }
        parts.push({
          type: 'image',
          mediaType: m[1],
          data: m[2],
          name: row.name + '×' + row.qty
        })
      })
      return parts
    }

    function feedBatch(payload, sessionId) {
      /* 同步抛错（取不到服务、依赖没声明之类）也必须变成一次「有提示的失败」，
         否则点了按钮什么都不会发生——之前就是这样静默掉的。 */
      try {
        return feedBatchRun(payload, sessionId)
      } catch (e) {
        return Promise.reject(reportFeedFail('投喂出错：' + ((e && e.message) || e), 'throw', sessionId || store.state.sessionId))
      }
    }

    function feedBatchRun(payload, sessionId) {
      var sessions = lookupSessions()
      var guess = sessionIdFromLocation()
      var sid = sessionId || store.state.sessionId || guess || ''
      diag('feed-start', { sessionId: sid, lookup: !!sessions, fromLocation: !sessionId && !store.state.sessionId ? guess : '' })
      if (!sessions) return Promise.reject(reportFeedFail('会话服务不可用，没法投喂', 'no-service', sid))
      if (!sid) return Promise.reject(reportFeedFail('还没连到会话：先打开一个对话', 'no-session', sid))
      if (!payload || !payload.text) return Promise.reject(reportFeedFail('这一批「购入美味」是空的', 'empty', sid))
      /* 1.7.0：这单要多少鲸元，余额不够就不发出去。 */
      var cost = num(payload.totals && payload.totals.tokens)
      if (num(store.state.balance) < cost) {
        return Promise.reject(reportFeedFail('余额不足：这单要 ' + cost + ' 鲸元，现在只有 ' + num(store.state.balance) + ' 鲸元（等进度条慢慢攒，或去「兑换」）', 'balance', sid))
      }
      /* 会话如果已经打开着，binding 里直接就有 session，可以绕过 retain/ready 这条最可能卡住的路。 */
      var direct = null
      try {
        if (typeof sessions.binding === 'function') direct = sessions.binding(sid)
      } catch (e) {
        direct = null
      }
      diag('feed-direct', { binding: !!direct, hasSession: !!(direct && direct.session) })
      var ref = null
      if (!(direct && direct.session && typeof (direct.session.prompt || direct.session.beginSubmission) === 'function')) {
        try {
          ref = sessions.retain(sid, { source: 'controllerOperation' })
        } catch (e) {
          return Promise.reject(reportFeedFail('取会话失败：' + ((e && e.message) || e), 'retain', sid))
        }
      }
      var released = false
      function release() {
        if (released) return
        released = true
        try { if (ref && ref.release) ref.release() } catch (e) {}
      }
      /* 等不到的 Promise 会让界面看起来「一点反应都没有」，所以每步都设上限。 */
      function withTimeout(p, ms, label) {
        return new Promise(function (resolve, reject) {
          var done = false
          var timer = setTimeout(function () {
            if (done) return
            done = true
            reject(reportFeedFail(label + '（' + ms + 'ms 没有响应）', 'timeout', sid))
          }, ms)
          Promise.resolve(p).then(function (v) {
            if (done) return
            done = true
            clearTimeout(timer)
            resolve(v)
          }, function (e) {
            if (done) return
            done = true
            clearTimeout(timer)
            reject(e)
          })
        })
      }
      /* 两种发消息的口子都试：prompt 是常规提交，beginSubmission 是输入框那条路。 */
      function submitText(session, payload) {
        if (session && typeof session.prompt === 'function') {
          var parts = feedParts(payload)
          diag('submit', { via: 'prompt', sessionId: sid, images: parts.length - 1 })
          return withTimeout(session.prompt(parts, 'queue'), 10000, '提交消息')
        }
        if (session && typeof session.beginSubmission === 'function') {
          diag('submit', { via: 'beginSubmission', sessionId: sid })
          /* BeginSubmissionInput 里 attachments 是必填，空数组也要给。 */
          return withTimeout(Promise.resolve(session.beginSubmission({ mode: 'queue', text: payload.text, attachments: [] })), 10000, '提交消息')
        }
        return Promise.reject(reportFeedFail('会话对象没有可用的发送方法', 'no-submit', sid))
      }
      var readyPromise = direct && direct.session ? Promise.resolve(direct) : withTimeout(ref.ready, 8000, '等会话就绪')
      return readyPromise.then(function (binding) {
        var session = binding && binding.session
        if (!session) throw reportFeedFail('会话没就绪（binding 里没有 session）', 'no-prompt', sid)
        return submitText(session, payload)
      }).then(function (res) {
        release()
        if (res && res.ok === false) {
          var err = res.error
          throw reportFeedFail('发送失败：' + ((err && (err.message || err.code)) || '未知原因'), 'prompt', sid)
        }
        applyPurchase(payload)
        diag('feed-ok', { sessionId: sid, tokens: num(payload.totals && payload.totals.tokens) })
        return true
      }, function (err) {
        release()
        if (err && err.stage) throw err
        throw reportFeedFail('会话没就绪：' + ((err && err.message) || err), 'ready', sid)
      })
    }

    function feedCurrent(sessionId) {
      var sid = sessionId || store.state.sessionId
      try {
        var payload = buildBatch()
        if (!payload) {
          reportFeedFail('先选货：把要买的东西挑上数量', 'no-picks', sid)
          flash('先选货：把要买的东西挑上数量', 'err')
          return
        }
        flash('正在把这批「购入美味」送进对话…', 'ok')
        feedBatch(payload, sid).then(function () {
          flash('已投喂给肥鱼，钱包记了一笔', 'ok')
        }).catch(function (err) {
          flash('投喂失败：' + ((err && err.message) || err), 'err')
        })
      } catch (e) {
        reportFeedFail('投喂出错：' + ((e && e.message) || e), 'throw', sid)
        flash('投喂失败：' + ((e && e.message) || e), 'err')
      }
    }
    /* ----------------------------------------------------------------- 货源 */

    var sourceProviders = []

    function registerSourceProvider(fn) {
      if (typeof fn !== 'function') return false
      sourceProviders.push(fn)
      return true
    }

    function runSearch() {
      var st = store.state
      var q = String(st.sourceQuery || '').trim().toLowerCase()
      var local = st.items.filter(function (it) {
        if (!q) return true
        var hay = [it.displayName, it.brand, it.category, it.tag, it.spec && it.spec.label]
          .filter(Boolean).join(' ').toLowerCase()
        return hay.indexOf(q) !== -1
      })
      store.set({
        panel: 'source',
        sourceResults: { local: local, external: null, loading: sourceProviders.length > 0 }
      })
      if (!sourceProviders.length) return
      Promise.all(sourceProviders.map(function (fn) {
        try {
          return Promise.resolve(fn(q)).catch(function () { return [] })
        } catch (e) { return [] }
      })).then(function (lists) {
        var rows = []
        ;(lists || []).forEach(function (list) {
          if (Array.isArray(list)) rows = rows.concat(list.filter(Boolean))
        })
        var cur = store.state.sourceResults
        store.set({
          sourceResults: { local: cur ? cur.local : local, external: rows, loading: false }
        })
      })
    }

    function addProviderItem(row) {
      if (!row || !row.name) return
      var tag = validTag(row.tag) ? row.tag : store.state.tab
      var parsed = parseName(row.name)
      var item = makeItem({
        name: String(row.name),
        displayName: stripExt(row.name),
        tag: tag,
        tagFrom: inferTag(row.name) ? 'name' : 'shelf',
        brand: parsed.brand,
        category: parsed.category,
        spec: parsed.spec,
        price: num(row.price) || DEFAULT_PRICE,
        qty: num(row.qty) || DEFAULT_STOCK,
        order: nextOrder(store.state.items)
      })
      var images = Object.assign({}, store.state.images)
      if (row.imageUrl) {
        images[item.id] = String(row.imageUrl)
        item.w = num(row.w) || 480
        item.h = num(row.h) || 360
        idbPut('img:' + item.id, images[item.id]).catch(function () {})
      }
      store.set({ items: store.state.items.concat([item]), images: images, tab: tag })
      saveMeta()
      flash('从货源入库一件「' + item.displayName + '」', 'ok')
    }

    /* ----------------------------------------------------------------- 窗口 */

    function defaultRect() {
      var vw = (typeof window !== 'undefined' && window.innerWidth) || 1440
      var vh = (typeof window !== 'undefined' && window.innerHeight) || 900
      var w = Math.min(1180, Math.max(680, vw - 360))
      var hgt = Math.min(840, Math.max(420, vh - 200))
      var x = Math.round((vw - w) / 2) + 60
      x = clamp(x, 16, Math.max(16, vw - w - 16))
      var y = 56
      return { x: x, y: y, w: w, h: hgt }
    }

    function openWindow() {
      var st = store.state
      var win = st.win || defaultRect()
      store.set({
        open: true,
        minimized: false,
        win: win
      })
    }

    function closeWindow() {
      store.set({ open: false, panel: null, settingsOpen: false })
    }

    function toggleWindow() {
      if (store.state.open) closeWindow()
      else openWindow()
    }

    function setTab(tag) {
      if (!validTag(tag) && !isOverview(tag)) return
      var order = [OVERVIEW].concat(TAGS.map(function (t) { return t.key }))
      var from = Math.max(0, order.indexOf(store.state.tab))
      var to = Math.max(0, order.indexOf(tag))
      /* 需求⑥：记下切换方向，界面按左右淡入淡出转场（往后翻从右进，往回翻从左进）。 */
      var patch = { tab: tag, tabDir: to >= from ? 1 : -1, confirmClear: false, marked: {} }
      if (validTag(tag)) patch.lastTag = tag
      store.set(patch)
      saveMeta()
      /* 1.5.2 需求④：点标签 / 切换货架都响「选中商品」。 */
      playSound('ding')
    }

    function cycleTab() {
      var order = [OVERVIEW].concat(TAGS.map(function (t) { return t.key }))
      var idx = Math.max(0, order.indexOf(store.state.tab))
      setTab(order[(idx + 1) % order.length])
    }

    /* 1.5.1：价格档只留一个按钮——第一次点「便宜在前」，再点就翻成「贵在前」。
       （1.5.0 那个「便宜在前 / 贵在前」并排的两颗已经并回来，见需求③。） */
    function setPriceDir(dir) {
      store.set({ arrange: 'price', priceDir: dir < 0 ? -1 : 1 })
      saveMeta()
    }

    function setArrange(mode) {
      if (mode === 'price') {
        /* 1.6.1：只有「便宜在前」一种，点几次都是升序，不会翻向。 */
        store.set({ arrange: 'price', priceDir: 1 })
        saveMeta()
        flash('价格排序：便宜在前（从低到高）', 'ok')
        return
      }
      store.set({ arrange: mode })
      saveMeta()
    }

    /* 1.6.0（需求①）：判定规则改完，点「刷新货架」按新规则重新归类 + 重排。
       手动改过标签的（tagFrom === 'manual'）一律不动——人工判断优先于自动识别。 */
    function refreshShelf() {
      var st = store.state
      var moved = 0
      var kept = 0
      var repriced = 0
      var items = st.items.map(function (it) {
        if (it.leaving) return it
        var next = it
        if (it.tagFrom === 'manual') {
          kept++
        } else {
          var guess = inferTag(it.name)
          /* 注意 validTag() 返回的是 true/false，标签名要用 guess 本身。 */
          if (!guess || !validTag(guess)) next = Object.assign({}, it, { tagFrom: 'shelf' })
          else if (guess !== it.tag) {
            moved++
            next = Object.assign({}, it, { tag: guess, tagFrom: 'name' })
          }
        }
        /* 需求⑨：默认价格改完点这里才生效——把标价重刷成它所属标签的默认价。 */
        var want = defaultPriceOf(next.tag)
        if (num(next.price) !== want) {
          repriced++
          next = Object.assign({}, next, { price: want })
        }
        return next
      })
      store.set({ items: items, marked: {}, moveOver: null, arrange: 'default' })
      saveMeta()
      playSound('ding')
      flash('刷新完成：重排了 ' + moved + ' 件、按默认价重标了 ' + repriced + ' 件，手动归类的 ' + kept + ' 件标签没动', 'ok')
    }

    /* ------------------------------------------------------------ 勾选 / 换货 */

    /* 1.5.0：勾选不再绑死在「当前这一页」——总览页里也能把不同货架的几件一起勾上。 */
    function markedItems(st) {
      st = st || store.state
      return st.items.filter(function (it) {
        return !it.leaving && st.marked[it.id]
      })
    }

    function toggleMark(id) {
      var marked = Object.assign({}, store.state.marked)
      if (marked[id]) delete marked[id]
      else marked[id] = true
      store.set({ marked: marked, confirmClear: false })
    }

    /* --------------------------------------------------- 拖动商品调整摆放顺序 */

    /* 把 fromId 插到 toId 的前面（after=true 则后面），只重排当前这一页，
       并把排货切回「默认」，否则品牌/品类分组会把刚摆好的顺序冲掉。 */
    function moveItem(fromId, toId, after) {
      if (!fromId || !toId || fromId === toId) return
      var st = store.state
      var movingItem = null
      st.items.forEach(function (it) { if (it.id === fromId) movingItem = it })
      if (!movingItem) return
      /* 拖动只在同一页货架内排顺序：总览页里按被拖那件自己的标签找同伙。 */
      var tag = movingItem.tag
      var shelf = st.items.filter(function (it) { return !it.leaving && it.tag === tag })
        .sort(function (a, b) { return num(a.order) - num(b.order) })
      var moving = null
      var rest = []
      shelf.forEach(function (it) {
        if (it.id === fromId) moving = it
        else rest.push(it)
      })
      if (!moving) return
      var idx = -1
      rest.forEach(function (it, i) { if (it.id === toId) idx = i })
      if (idx < 0) return
      rest.splice(after ? idx + 1 : idx, 0, moving)
      var orders = {}
      rest.forEach(function (it, i) { orders[it.id] = i })
      var items = st.items.map(function (it) {
        if (orders[it.id] === undefined) return it
        return Object.assign({}, it, { order: orders[it.id] })
      })
      store.set({ items: items, arrange: 'default', moveId: null, moveOver: null })
      saveMeta()
      flash('顺序已按你摆的排好', 'ok')
    }

    /* -------------------------------------------------------------- 排货分组 */

    function areaBucket(area, t1, t2) {
      if (!area || !t1 || !t2) return ''
      if (area >= t2) return '大'
      if (area <= t1) return '小'
      return '中'
    }

    function groupKeyOf(item, mode, t1, t2) {
      if (mode === 'brand') return item.brand ? ('品牌 · ' + item.brand) : '品牌 · 未标注品牌'
      if (mode === 'category') return item.category ? ('品类 · ' + item.category) : '品类 · 未标注品类'
      if (mode === 'spec') {
        if (item.spec && item.spec.label) return '规格 · ' + item.spec.label
        var b = areaBucket((item.w || 0) * (item.h || 0), t1, t2)
        return b ? ('体型 · ' + b + '（按图）') : '规格 · 未标注'
      }
      return ''
    }

    function compareGroupKey(a, b) {
      var ua = a.indexOf('未标注') !== -1
      var ub = b.indexOf('未标注') !== -1
      if (ua !== ub) return ua ? 1 : -1
      var na = a.match(/(\d+(?:\.\d+)?)/)
      var nb = b.match(/(\d+(?:\.\d+)?)/)
      if (na && nb) {
        var va = parseFloat(na[1])
        var vb = parseFloat(nb[1])
        if (va !== vb) return vb - va
      }
      return zhCompare(a, b)
    }

    function arrangeItems(items, mode) {
      if (!mode || mode === 'default') {
        return [{ key: '', items: items.slice().sort(function (a, b) { return a.order - b.order }) }]
      }
      /* 价格排：不分堆，就是一条按标价排好的队列（升 / 降由 priceDir 决定）。 */
      if (mode === 'price') {
        var dir = num(store.state.priceDir) < 0 ? -1 : 1
        return [{
          key: '按标价 · ' + (dir > 0 ? '便宜在前' : '贵在前'),
          items: items.slice().sort(function (a, b) {
            var d = (num(a.price) - num(b.price)) * dir
            return d || zhCompare(a.displayName, b.displayName)
          })
        }]
      }
      var areas = []
      items.forEach(function (it) {
        var a = (it.w || 0) * (it.h || 0)
        if (a > 0) areas.push(a)
      })
      areas.sort(function (a, b) { return a - b })
      var t1 = areas.length >= 3 ? areas[Math.floor(areas.length / 3)] : 0
      var t2 = areas.length >= 3 ? areas[Math.floor((areas.length * 2) / 3)] : 0
      var map = {}
      var keys = []
      items.forEach(function (it) {
        var k = groupKeyOf(it, mode, t1, t2)
        if (!map[k]) { map[k] = []; keys.push(k) }
        map[k].push(it)
      })
      keys.sort(compareGroupKey)
      return keys.map(function (k) {
        return {
          key: k,
          items: map[k].sort(function (a, b) { return zhCompare(a.displayName, b.displayName) })
        }
      })
    }

